"""Build the standalone Raylab editorial catalogue; reuse the site's brand and artwork."""
from pathlib import Path
from html import escape
from PIL import Image
import base64
import io
import re

ROOT = Path(__file__).resolve().parents[3]
DIST = ROOT / 'web/dist'
ART = DIST/'img/catalogo'
ART.mkdir(parents=True, exist_ok=True)
# JPEG keeps photographs sharp while preventing large lossless images in the PDF.
for source in (DIST/'img/services').glob('*-visual.webp'):
    with Image.open(source) as image:
        image.convert('RGB').save(ART/(source.stem+'.jpg'), quality=89, optimize=True)
# Preserve the official symbol, rasterizing only its existing embedded image at
# four times its display size. The viewBox and image coordinates come from logo.svg.
symbol_svg=(DIST/'img/logo.svg').read_text(encoding='utf-8')
embedded=re.search(r'data:image/webp;base64,([^"\s]+)',symbol_svg).group(1)
with Image.open(io.BytesIO(base64.b64decode(embedded))) as symbol:
    width,height=symbol.size
    symbol=symbol.crop((95/775*width,123/775*height,695/775*width,743/775*height))
    symbol.thumbnail((168,174),Image.Resampling.LANCZOS)
    symbol.save(ART/'logo.png',optimize=True)

